import type { AtRule, Declaration, Rule } from "postcss";
import { type SyntaxRaw } from "../../utils/typeGuards/index.ts";
/**
 * Returns the raw a syntax keeps beside a node's text: `raws.value`, `raws.selector` or `raws.params`.
 * @param node - The declaration, rule or at-rule.
 * @returns The raw, where the parser filled one.
 */
export declare function rawsOf(node: AtRule | Declaration | Rule): SyntaxRaw | undefined;
/**
 * Returns a node's text as the file spells it.
 *
 * PostCSS keeps the text with its comments in a raw beside the comment-less copy on the node, and `postcss-scss` prints from a `scss` copy of its own with the raw's `//` comments rewritten. Warnings are counted in the printed copy and a fix can reach no other, so `scss` is read first, then the raw, both only while the raw's `value` is the node's own text, as the stringifiers print them; otherwise the node's own text.
 * @param node - The declaration, rule or at-rule.
 * @returns The text as spelled.
 */
export declare function printedText(node: AtRule | Declaration | Rule): string;
/**
 * Writes a node's text into the copy the syntax prints, keeping its other copies in step.
 *
 * Under `postcss-scss` the `scss` copy takes the fix and the raw is rebuilt with its `//` comments rewritten, so a later rule still reads two copies of one text; writing the node's own property would have PostCSS drop both raws. The rewriting is the parser's own — the comments are cut where `postcss-scss` cuts them, so the pair comes back the shape it would have parsed as, and a later reader of it is not handed a comment the file does not spell.
 * @param node - The declaration, rule or at-rule.
 * @param text - The text to write.
 */
export declare function writePrintedText(node: AtRule | Declaration | Rule, text: string): void;
